  'pj.models': L(['Логистическая регрессия', 'Случайный лес', 'XGBoost', 'CatBoost', 'Логистическая, только погода', 'Сезонная база'], ['Logistic regression', 'Random forest', 'XGBoost', 'CatBoost', 'Logistic, weather only', 'Seasonal baseline'], ['Логистикалық регрессия', 'Кездейсоқ орман', 'XGBoost', 'CatBoost', 'Логистикалық, тек ауа райы', 'Маусымдық негіз']),
  'pj.features': L(
    ['Плотность населения', 'Сезон, косинус месяца', 'Сезон, синус месяца', 'Температура за 14 дней', 'Температура за 7 дней', 'Пашня', 'Высота', 'Прочий покров', 'NDVI', 'Уклон', 'Влажность почвы', 'Максимальная температура', 'Минимальная температура', 'Экспозиция склона, cos', 'Экспозиция склона, sin', 'Расстояние до поселений', 'Осадки за 14 дней', 'Осадки за 7 дней', 'Осадки за сутки', 'Относительная влажность', 'Луга', 'Ветер', 'Нет наблюдения NDVI', 'Давность NDVI, дней', 'Лес', 'Кустарник'],
    ['Population density', 'Season, month cosine', 'Season, month sine', 'Temperature over 14 days', 'Temperature over 7 days', 'Cropland', 'Elevation', 'Other cover', 'NDVI', 'Slope', 'Soil moisture', 'Maximum temperature', 'Minimum temperature', 'Slope aspect, cos', 'Slope aspect, sin', 'Distance to settlements', 'Precipitation over 14 days', 'Precipitation over 7 days', 'Daily precipitation', 'Relative humidity', 'Grassland', 'Wind', 'No NDVI observation', 'NDVI age, days', 'Forest', 'Shrubland'],
    ['Халық тығыздығы', 'Маусым, ай косинусы', 'Маусым, ай синусы', '14 күндік температура', '7 күндік температура', 'Егістік', 'Биіктік', 'Басқа жамылғы', 'NDVI', 'Еңіс', 'Топырақ ылғалдылығы', 'Ең жоғары температура', 'Ең төменгі температура', 'Беткей экспозициясы, cos', 'Беткей экспозициясы, sin', 'Елді мекендерге дейінгі қашықтық', '14 күндік жауын-шашын', '7 күндік жауын-шашын', 'Тәуліктік жауын-шашын', 'Салыстырмалы ылғалдылық', 'Шалғындар', 'Жел', 'NDVI бақылауы жоқ', 'NDVI мерзімі, күн', 'Орман', 'Бұталар']),
  'pj.best': L('лучшая из шести моделей', 'best of six models', 'алты модельдің ең үздігі'),
  'pj.at': L(({ t }) => `при пороге ${t}`, ({ t }) => `at threshold ${t}`, ({ t }) => `${t} шегінде`),
  'pj.apTitle': L('Average precision на 2023–2024', 'Average precision on 2023–2024', '2023–2024 жылдардағы average precision'),
  'pj.beforeTest': L('выбрана до теста', 'chosen before the test', 'тестке дейін таңдалды'),
  'pj.calTitle': L('Калибровка XGBoost', 'XGBoost calibration', 'XGBoost калибрлеуі'),
  'pj.impTitle': L('Средний |вклад| признака, лог-шансы · 15 сильнейших', 'Mean |contribution| per feature, log-odds · top 15', 'Белгінің орташа |үлесі|, лог-мүмкіндіктер · ең күшті 15'),
  'pj.cpu': L(({ h }) => `Процессорное время процесса, суммарно по всем потокам: ${h} CPU·ч. Это отдельное измерение Windows GetProcessTimes за всё время жизни процесса; оно не равно календарному времени запуска.`,
    ({ h }) => `Process CPU time summed over all threads: ${h} CPU·h. This is a separate Windows GetProcessTimes measurement over the whole process lifetime; it is not the calendar run time.`,
    ({ h }) => `Процестің барлық ағындар бойынша жиынтық процессор уақыты: ${h} CPU·сағ. Бұл процестің бүкіл өмір сүру уақытындағы Windows GetProcessTimes жеке өлшемі; ол іске қосудың күнтізбелік уақытына тең емес.`),
  'pj.sample': L('Выборка', 'Sample', 'Іріктеме'),
